from pathlib import Path
import json, re, hashlib
from html.parser import HTMLParser

class Text(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.skip = 0
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.skip += 1
    def handle_endtag(self, tag):
        if tag in ('script', 'style') and self.skip:
            self.skip -= 1
        if tag in ('p', 'li', 'h1', 'h2', 'h3', 'tr') and not self.skip:
            self.parts.append('\n')
    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)

root = Path('products/services/catalogue-qa-digital-checkout')
for name, pattern in {
    'store-activation': r'identity|review|test mode|business|approv|application|payout',
    'prohibited-products': r'artificial intelligence|AI.generated|digital|services|rights|marketplace',
    'fees': r'5%|50¢|0\.50|international|subscription|payout|monthly',
    'supported-countries': r'Canada|bank|PayPal|payout',
}.items():
    path = root / 'raw' / (name + '.html')
    raw = path.read_bytes()
    parser = Text()
    parser.feed(raw.decode('utf-8'))
    rows = [' '.join(line.split()) for line in ''.join(parser.parts).splitlines()]
    clauses = list(dict.fromkeys(row for row in rows if re.search(pattern, row, re.I)))
    print(json.dumps({'source_file': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'candidate_passages': [row[:500] for row in clauses[:12]]}, ensure_ascii=False))
print(json.dumps({'existing_checkout_outputs': sorted(p.name for p in root.iterdir() if p.is_file()), 'catalogue_download_files': sorted(str(p) for p in Path('products/sites/shopify-catalogue-example').rglob('*') if p.is_file())}))
